    const meta3 = await getRozsireneByIri(versionIri);
    const validity = await describeVersionValidity(baseIri, versionIri, meta3);
    const portalHtml = await getPortalHtml(versionIri);
    const maxChars = max_chars ?? 5e4;
    const rendered = renderWholeLawTextChunk(portalHtml, { maxChars, offsetChars: 0 });
    const fileBase = `${number4}-${year}_${resolvedDate}`;
